// A small stick-framed building as the simulation will see it once build mode's construction half reports real
// members: generated by src/framing.js (the same code the page uses) and turned into pieces the way build.js does.
import '../../src/framing.js';
import { mapPieces } from '../../src/sim/site.js';
const F = globalThis.__framing;
export const STAGES = F.STAGES;

// a W x D m cabin with a gable roof along x, a door in the front wall and a window in the back one
export function framedCabin({ W = 3, D = 2.4, found = 'pier-blocks', H = 2.84 } = {}) {
  const ov = 0.45, half = D / 2, rise = Math.max(0.7, half * 0.85), run = half + ov, sl = rise / half, pts = (x, z) => ({ x, z });
  const planes = [-1, 1].map((side, n) => ({ id: 'r.' + n, pts: [[-ov, half + side * run], [W + ov, half + side * run], [W + ov, half], [-ov, half]], eaveY: H - sl * ov, ridgeY: H + rise, run, facing: [0, side], overhang: ov }));
  const topAt = (x, z) => H + rise - sl * Math.abs(z - half);
  const desc = { found, spec: { ins: 'fibreglass_batt', lining: 'boards' },
    floors: [{ id: 'f', outline: [[0, 0], [W, 0], [W, D], [0, D]], y0: 0, ground: true, mat: 'planks' }],
    walls: [{ id: 'wb', a: [0, 0], b: [W, 0], y0: 0, h: H, out: -1, mat: 'timber', openings: [{ id: 'o1', kind: 'window', offset: 1.1, width: 0.8, sill: 1.11, height: 0.78 }] },
      { id: 'wf', a: [0, D], b: [W, D], y0: 0, h: H, out: 1, mat: 'timber', openings: [{ id: 'o2', kind: 'door', offset: 1.0, width: 0.82, sill: 0.05, height: 1.99 }] },
      { id: 'wl', a: [0, 0], b: [0, D], y0: 0, h: H, out: 1, mat: 'timber', openings: [] }, { id: 'wr', a: [W, 0], b: [W, D], y0: 0, h: H, out: -1, mat: 'timber', openings: [] }],
    roofs: [{ id: 'r', mat: 'shingle', planes, ridges: [{ a: [-ov, half], b: [W + ov, half], y: H + rise }], infills: [{ id: 'r.g0', a: [0, 0], b: [0, D], y0: H, y1: H + rise, area: D * rise / 2, top: topAt }, { id: 'r.g1', a: [W, 0], b: [W, D], y0: H, y1: H + rise, area: D * rise / 2, top: topAt }],
      ties: [0.4, W / 2, W - 0.4].map((x) => ({ a: [x, 0], b: [x, D], y: H })) }] };
  const mem = F.generate(desc), head = (id, kind, type, material) => ({ id, struct: 1, storey: 0, kind, type, material, built: true }), out = [];
  const rect = [pts(0, 0), pts(W, 0), pts(W, D), pts(0, D)], drop = F.FOUNDATIONS[found].drop;
  out.push({ ...head('f', 'floor', 'floor', 'planks'), a: pts(0, 0), b: pts(W, D), y0: 0, y1: F.FLOOR_T, thickness: F.FLOOR_T, area: W * D, outline: rect, holes: [], layers: [] });
  out.push({ ...head('f.fd', 'foundation', found, 'stone'), a: pts(0, 0), b: pts(W, D), y0: -drop, y1: 0, height: drop, area: W * D, outline: rect, holes: [], floor: 'f' });
  for (const w of desc.walls) { const L = Math.hypot(w.b[0] - w.a[0], w.b[1] - w.a[1]);
    out.push({ ...head(w.id, 'wall', 'wall', 'timber'), a: pts(...w.a), b: pts(...w.b), y0: 0, y1: H, length: L, height: H, thickness: 0.13, area: L * H, netArea: L * H - w.openings.reduce((s, o) => s + o.width * o.height, 0), layers: [],
      openings: w.openings.map((o) => ({ ...o, y0: o.sill, y1: o.sill + o.height, area: o.width * o.height, fill: o.kind === 'door' ? 'leaf' : 'glazing' })) }); }
  const pitch = Math.atan2(rise + sl * ov, run);
  for (const pl of planes) out.push({ ...head(pl.id, 'roof', 'gable', 'shingle'), roof: 'r', a: pts(...pl.pts[0]), b: pts(...pl.pts[1]), y0: pl.eaveY, y1: pl.ridgeY, eaveY: pl.eaveY, ridgeY: pl.ridgeY, pitchDeg: pitch * 180 / Math.PI, length: W + 2 * ov,
    planArea: (W + 2 * ov) * run, area: (W + 2 * ov) * run / Math.cos(pitch), thickness: 0.2, footprint: pl.pts.map((q) => pts(...q)), facing: { x: pl.facing[0], z: pl.facing[1] }, layers: [] });
  for (const g of desc.roofs[0].infills) out.push({ ...head(g.id, 'wall', 'gable', 'timber'), roof: 'r', a: pts(...g.a), b: pts(...g.b), y0: H - 0.02, y1: g.y1, length: D, height: g.y1 - H + 0.02, thickness: 0.13, area: g.area, netArea: g.area, shape: 'triangle', layers: [], openings: [] });
  for (const p of out) { const k = mem.filter((m) => m.parent === p.id); if (k.length) p.members = k.map((m) => m.id); }
  for (const m of mem) {                                           // as build.js reports a member
    const ax = m.b[0] - m.a[0], ay = m.b[1] - m.a[1], az = m.b[2] - m.a[2], al = Math.hypot(ax, ay, az) || 1, wy = (az * m.n[0] - ax * m.n[2]) / al, e = (Math.abs(m.n[1]) * m.section.d + Math.abs(wy) * m.section.b) / 2;
    const q = { ...head(m.id, m.kind, m.type, m.material), stage: m.stage, parent: m.parent, section: m.section, length: m.length, a: pts(m.a[0], m.a[2]), b: pts(m.b[0], m.b[2]), y0: Math.min(m.a[1], m.b[1]) - e, y1: Math.max(m.a[1], m.b[1]) + e };
    for (const f of ['area', 'thickness', 'volume', 'size', 'plies', 'roof', 'opening', 'height']) if (m[f] !== undefined) q[f] = m[f];
    out.push(q);
  }
  return mapPieces(out);
}
// the same building part-way up: every member of a stage after `stage` is still only planned
export function builtTo(pieces, stage) {
  const n = STAGES.indexOf(stage), done = new Map(pieces.filter((p) => p.stage).map((p) => [p.id, STAGES.indexOf(p.stage) <= n]));
  return pieces.map((p) => (p.stage ? { ...p, built: done.get(p.id) } : p.members ? { ...p, built: p.members.every((id) => done.get(id)) } : p));
}
